with zipfile.ZipFile(zip_path) as z:
 assert z.testzip() is None
 names=z.namelist();assert 'START_HERE.html' in names and 'NES_Forge.html' in names
 # A long but realistic destination catches Explorer's legacy path limit.
 # Short ZIP names alone are insufficient if another root folder is embedded.
 destination='C:/'+'d'*156
 windows_paths=[destination+'/'+n for n in names]
 units=lambda value:len(value.encode('utf-16-le'))//2
 assert len({n.casefold() for n in names})==len(names),'Windows filename collision'
 for name,full in zip(names,windows_paths):
  assert units(full)<260,('Windows extraction file path too long',name)
  assert units(full.rsplit('/',1)[0])<248,('Windows directory path too long',name)
  for part in name.split('/'):
   assert part not in ('.','..') and not part.endswith(('.', ' ')) and not re.search(r'[<>:"\\|?*\x00-\x1f]',part),('Invalid Windows name',name)
   assert part.split('.')[0].upper() not in {'CON','PRN','AUX','NUL',*[f'COM{i}' for i in range(1,10)],*[f'LPT{i}' for i in range(1,10)]},('Reserved Windows name',name)
 windows_check={'status':'passed','zipHasExtraEnclosingFolder':False,'entries':len(names),'maxRelativePathUTF16Units':max(map(units,names)),'simulatedDestinationUTF16Units':units(destination),'maxDestinationFilePathUTF16Units':max(map(units,windows_paths)),'maxDestinationDirectoryPathUTF16Units':max(units(p.rsplit('/',1)[0]) for p in windows_paths),'limits':{'filePathBelow':260,'directoryPathBelow':248},'suggestedWindowsDestination':'C:/NF','nativeWindowsExplorerTested':False}
 (Path(__file__).parent/'Windows_Zip_Check.json').write_text(json.dumps(windows_check,indent=2)+'\n')
